def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); components=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); pts=[]
                while stack:
                    y,x=stack.pop(); pts.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen:
                                seen.add((ny,nx)); stack.append((ny,nx))
                r0=min(y for y,x in pts); r1=max(y for y,x in pts)
                c0=min(x for y,x in pts); c1=max(x for y,x in pts)
                arr=[[grid[y][x] for x in range(c0,c1+1)] for y in range(r0,r1+1)]
                components.append(arr)
    pairs=[]
    for i in range(len(components)):
        for j in range(i+1,len(components)):
            a,b=components[i],components[j]
            if len(a)==len(b) and len(a[0])==len(b[0]):
                diff=sum((a[r][c]==0)!=(b[r][c]==0) for r in range(len(a)) for c in range(len(a[0])))
                pairs.append((diff,a,b))
    if not pairs: raise ValueError('no matching component pair')
    _,a,b=min(pairs,key=lambda z:-z[0]) # select pair with largest defect mask
    mask=[[(8 if ((a[r][c]==0)!=(b[r][c]==0)) else 0) for c in range(len(a[0]))] for r in range(len(a))]
    rows=[r for r in range(len(mask)) if any(mask[r])]
    cols=[c for c in range(len(mask[0])) if any(mask[r][c] for r in range(len(mask)))]
    if not rows:return [[0]]
    return [row[min(cols):max(cols)+1] for row in mask[min(rows):max(rows)+1]]
